#include "chain.c"
__location(0xC600) u16 result[8];
u8 SND_TraceX[8];u8 SND_TraceY[8];u8 SND_TraceDir[8];
u8 SND_HeadX;u8 SND_HeadY;u8 SND_Facing;u8 SND_Length;
#define SND_SCREEN_W 160
#define SND_SCREEN_H 144
#define SND_SEGMENT_GAP 4
static u8 SND_AbsS16ToU8(s16 v){if(v<0)v=(s16)(0-v);if(v>255)return 255;return (u8)v;}
static void SND_AudioServiceWork(u8 i){}
/* Choose the shortest signed displacement across the wraparound playfield. */
static s16 SND_ShortDelta(u8 cur, u8 prev, u8 size)
{
    s16 d;
    s16 half;

    d = (s16)((s16)cur - (s16)prev);
    half = (s16)(size >> 1);
    if (d > half) d = (s16)(d - (s16)size);
    else if (d < (s16)(0 - half)) d = (s16)(d + (s16)size);
    return d;
}

static u8 SND_WrapCoord(s16 v, u8 size)
{
    while (v < 0) {
        v = (s16)(v + (s16)size);
    }
    while (v >= (s16)size) {
        v = (s16)(v - (s16)size);
    }
    return (u8)v;
}

/* Bound each joint's correction instead of snapping it to its target socket. */
static s16 SND_SocketStep(s16 delta)
{
    u8 dist;

    dist = SND_AbsS16ToU8(delta);
    if (dist == 0) return 0;
    if (delta < 0) {
        if (dist > SND_SEGMENT_GAP) return (s16)(0 - 2);
        return (s16)(0 - 1);
    }
    if (dist > SND_SEGMENT_GAP) return 2;
    return 1;
}

static s16 SND_LinkOffsetX(u8 sector)
{
    if (sector == 0) return 4;
    if (sector == 1) return 4;
    if (sector == 2) return 3;
    if (sector == 3) return 1;
    if (sector == 4) return 0;
    if (sector == 5) return (s16)(0 - 1);
    if (sector == 6) return (s16)(0 - 3);
    if (sector == 7) return (s16)(0 - 4);
    if (sector == 8) return (s16)(0 - 4);
    if (sector == 9) return (s16)(0 - 4);
    if (sector == 10) return (s16)(0 - 3);
    if (sector == 11) return (s16)(0 - 1);
    if (sector == 12) return 0;
    if (sector == 13) return 1;
    if (sector == 14) return 3;
    return 4;
}

static s16 SND_LinkOffsetY(u8 sector)
{
    if (sector == 0) return 0;
    if (sector == 1) return 1;
    if (sector == 2) return 3;
    if (sector == 3) return 4;
    if (sector == 4) return 4;
    if (sector == 5) return 4;
    if (sector == 6) return 3;
    if (sector == 7) return 1;
    if (sector == 8) return 0;
    if (sector == 9) return (s16)(0 - 1);
    if (sector == 10) return (s16)(0 - 3);
    if (sector == 11) return (s16)(0 - 4);
    if (sector == 12) return (s16)(0 - 4);
    if (sector == 13) return (s16)(0 - 4);
    if (sector == 14) return (s16)(0 - 3);
    return (s16)(0 - 1);
}

static void SND_PullJoint(u8 joint, u8 pull_dir)
{
    u8 prev;
    u8 px;
    u8 py;
    u8 cx;
    u8 cy;
    u8 tx;
    u8 ty;
    s16 dx;
    s16 dy;
    s16 sx;
    s16 sy;

    prev = (u8)(joint - 1);
    px = SND_TraceX[(__safe_index u8)prev];
    py = SND_TraceY[(__safe_index u8)prev];
    cx = SND_TraceX[(__safe_index u8)joint];
    cy = SND_TraceY[(__safe_index u8)joint];
    /* Aim one link behind the preceding joint using its propagated heading. */
    tx = SND_WrapCoord((s16)((s16)px - SND_LinkOffsetX(pull_dir)), SND_SCREEN_W);
    ty = SND_WrapCoord((s16)((s16)py - SND_LinkOffsetY(pull_dir)), SND_SCREEN_H);

    dx = SND_ShortDelta(tx, cx, SND_SCREEN_W);
    dy = SND_ShortDelta(ty, cy, SND_SCREEN_H);
    sx = SND_SocketStep(dx);
    sy = SND_SocketStep(dy);
    SND_TraceDir[(__safe_index u8)joint] = pull_dir;
    if (sx == 0 && sy == 0) return;

    SND_TraceX[(__safe_index u8)joint] = SND_WrapCoord((s16)((s16)cx + sx), SND_SCREEN_W);
    SND_TraceY[(__safe_index u8)joint] = SND_WrapCoord((s16)((s16)cy + sy), SND_SCREEN_H);
}

static void SND_UpdateArticulatedBody()
{
    u8 i;
    u8 pull_dir;
    u8 old_dir;

    SND_TraceX[0] = SND_HeadX;
    SND_TraceY[0] = SND_HeadY;
    SND_TraceDir[0] = SND_Facing;

    pull_dir = SND_Facing;
    i = 1;
    while (i < SND_Length) {
        /* Pass the OLD heading onward; passing the new one would rotate the
           entire body together instead of propagating a bend one joint at a time. */
        old_dir = SND_TraceDir[(__safe_index u8)i];
        SND_PullJoint(i, pull_dir);
        pull_dir = old_dir;
        i = (u8)(i + 1);
        SND_AudioServiceWork(i);
    }
}


ChainBody body;u8 bx[8];u8 by[8];u8 bd[8];
void main(){u8 d;u8 i;u8 tick;
result[0]=0;result[1]=0;result[2]=0;
chain_body_init(&body,bx,by,bd,8,160,144);
for(d=0;d<16;d++){
 chain_body_reset(&body,8,2,142,12);SND_Length=8;
 for(i=0;i<8;i++){SND_TraceX[i]=bx[i];SND_TraceY[i]=by[i];SND_TraceDir[i]=bd[i];}
 for(tick=0;tick<4;tick++){
 SND_HeadX=(u8)((tick*53+d*7)%160);SND_HeadY=(u8)((tick*47+d*5)%144);SND_Facing=d;
 SND_UpdateArticulatedBody();chain_body_step(&body,SND_HeadX,SND_HeadY,SND_Facing);
 for(i=0;i<8;i++){
 if(bx[i]!=SND_TraceX[i]||by[i]!=SND_TraceY[i]||bd[i]!=SND_TraceDir[i]){result[0]++;}
 }
 result[1]++;
 }
}
result[2]=0xA55A;while(1){}
}

